#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Validates outputs from the upstream pipeline and generates a validation summary.
"""

import json
import os
import sys
import csv
from pathlib import Path

# Configuration
OUTPUT_DIR = Path("outputs")
SUMMARY_FILE = OUTPUT_DIR / "t14_validation_summary.json"

# Expected file structure
EXPECTED_FILES = {
    "t01_selected_indicators.csv": {
        "columns": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
        "min_rows": 1,
        "description": "Selected indicators with metadata"
    },
    "t05_clean_stops.csv": {
        "columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
        "min_rows": 1,
        "description": "Cleaned stop times data"
    },
    "t08_pois_clean.csv": {
        "columns": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
        "min_rows": 1,
        "description": "Cleaned POI data"
    },
    "t10_accessibility_scores.csv": {
        "columns": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
        "min_rows": 1,
        "description": "Accessibility scores for POIs"
    },
    "t13_city_clusters.csv": {
        "columns": ["city_id", "cluster_id", "cluster_name", "member_count"],
        "min_rows": 1,
        "description": "City cluster assignments"
    }
}

# Validation checks
def check_file_exists(filepath):
    """Check if file exists."""
    return os.path.exists(filepath)

def check_file_not_empty(filepath):
    """Check if file is not empty."""
    if not os.path.exists(filepath):
        return False
    return os.path.getsize(filepath) > 0

def check_columns(filepath, expected_columns):
    """Check if file has expected columns."""
    if not os.path.exists(filepath):
        return False, "File does not exist"

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            columns = reader.fieldnames
            missing_columns = [col for col in expected_columns if col not in columns]
            if missing_columns:
                return False, f"Missing columns: {missing_columns}"
            return True, "All expected columns present"
    except Exception as e:
        return False, f"Error reading file: {str(e)}"

def check_row_count(filepath, min_rows=1):
    """Check if file has at least min_rows rows."""
    if not os.path.exists(filepath):
        return False, "File does not exist"

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            row_count = sum(1 for _ in reader)
            if row_count < min_rows:
                return False, f"File has {row_count} rows, expected at least {min_rows}"
            return True, f"File has {row_count} rows"
    except Exception as e:
        return False, f"Error reading file: {str(e)}"

def validate_file(filepath, file_config):
    """Validate a single file against its configuration."""
    results = []

    # Check file exists
    if not check_file_exists(filepath):
        results.append({
            "check_name": "file_exists",
            "passed": False,
            "message": f"File {os.path.basename(filepath)} does not exist"
        })
        return results

    # Check file not empty
    if not check_file_not_empty(filepath):
        results.append({
            "check_name": "file_not_empty",
            "passed": False,
            "message": f"File {os.path.basename(filepath)} is empty"
        })
        return results

    # Check columns
    if not check_columns(filepath, file_config["columns"])[0]:
        results.append({
            "check_name": "columns_present",
            "passed": False,
            "message": file_config["columns"]
        })
        return results

    # Check row count
    if not check_row_count(filepath, file_config["min_rows"])[0]:
        results.append({
            "check_name": "row_count",
            "passed": False,
            "message": file_config["min_rows"]
        })

    return results

def validate_pipeline_outputs():
    """Validate all pipeline outputs."""
    all_results = []

    for filename, config in EXPECTED_FILES.items():
        filepath = OUTPUT_DIR / filename

        # Add file existence check
        if not check_file_exists(filepath):
            all_results.append({
                "check_name": f"{filename}_exists",
                "passed": False,
                "message": f"Expected output {filename} is missing"
            })
            continue

        # Add file not empty check
        if not check_file_not_empty(filepath):
            all_results.append({
                "check_name": f"{filename}_not_empty",
                "passed": False,
                "message": f"Expected output {filename} is empty"
            })
            continue

        # Add column validation
        if not check_columns(filepath, config["columns"])[0]:
            all_results.append({
                "check_name": f"{filename}_columns",
                "passed": False,
                "message": f"Expected output {filename} has incorrect columns"
            })
            continue

        # Add row count validation
        if not check_row_count(filepath, config["min_rows"])[0]:
            all_results.append({
                "check_name": f"{filename}_row_count",
                "passed": False,
                "message": f"Expected output {filename} has insufficient rows"
            })
            continue

        # Add specific validation for each file type
        if filename == "t01_selected_indicators.csv":
            results = validate_indicators(filepath)
            all_results.extend(results)
        elif filename == "t05_clean_stops.csv":
            results = validate_stops(filepath)
            all_results.extend(results)
        elif filename == "t08_pois_clean.csv":
            results = validate_pois(filepath)
            all_results.extend(results)
        elif filename == "t10_accessibility_scores.csv":
            results = validate_accessibility(filepath)
            all_results.extend(results)
        elif filename == "t13_city_clusters.csv":
            results = validate_clusters(filepath)
            all_results.extend(results)

    # Write summary
    with open(SUMMARY_FILE, 'w', encoding='utf-8') as f:
        json.dump(all_results, f, indent=2)

    return all_results

def validate_indicators(filepath):
    """Validate t01_selected_indicators.csv"""
    results = []

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": "t01_has_data",
                    "passed": False,
                    "message": "t01_selected_indicators.csv has no data rows"
                })
                return results

            # Check indicator_id format
            for row in rows:
                if not row.get("indicator_id"):
                    results.append({
                        "check_name": "t01_indicator_id_format",
                        "passed": False,
                        "message": "t01_selected_indicators.csv has missing indicator_id"
                    })
                    break

            # Check expected_direction values
            valid_directions = ["lower_is_better", "higher_is_better", "no_preference"]
            for row in rows:
                direction = row.get("expected_direction", "")
                if direction and direction not in valid_directions:
                    results.append({
                        "check_name": "t01_expected_direction_valid",
                        "passed": False,
                        "message": f"t01_selected_indicators.csv has invalid expected_direction: {direction}"
                    })
                    break

            results.append({
                "check_name": "t01_has_data",
                "passed": True,
                "message": f"t01_selected_indicators.csv has {len(rows)} valid rows"
            })
    except Exception as e:
        results.append({
            "check_name": "t01_validation",
            "passed": False,
            "message": f"Error validating t01_selected_indicators.csv: {str(e)}"
        })

    return results

def validate_stops(filepath):
    """Validate t05_clean_stops.csv"""
    results = []

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": "t05_has_stops",
                    "passed": False,
                    "message": "t05_clean_stops.csv has no data rows"
                })
                return results

            # Check stop_lat and stop_lon are valid floats
            for row in rows:
                try:
                    lat = float(row.get("stop_lat", ""))
                    lon = float(row.get("stop_lon", ""))

                    if not (-90 <= lat <= 90):
                        results.append({
                            "check_name": "t05_coordinates_valid",
                            "passed": False,
                            "message": "t05_clean_stops.csv has invalid latitude"
                        })
                        break

                    if not (-180 <= lon <= 180):
                        results.append({
                            "check_name": "t05_coordinates_valid",
                            "passed": False,
                            "message": "t05_clean_stops.csv has invalid longitude"
                        })
                        break
                except ValueError:
                    results.append({
                        "check_name": "t05_coordinates_valid",
                        "passed": False,
                        "message": "t05_clean_stops.csv has non-numeric coordinates"
                    })
                    break

            results.append({
                "check_name": "t05_has_stops",
                "passed": True,
                "message": f"t05_clean_stops.csv has {len(rows)} valid stop records"
            })
    except Exception as e:
        results.append({
            "check_name": "t05_validation",
            "passed": False,
            "message": f"Error validating t05_clean_stops.csv: {str(e)}"
        })

    return results

def validate_pois(filepath):
    """Validate t08_pois_clean.csv"""
    results = []

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": "t08_has_pois",
                    "passed": False,
                    "message": "t08_pois_clean.csv has no data rows"
                })
                return results

            # Check qid format (should be Q followed by numbers)
            for row in rows:
                qid = row.get("qid", "")
                if not qid.startswith("Q"):
                    results.append({
                        "check_name": "t08_qid_format",
                        "passed": False,
                        "message": "t08_pois_clean.csv has invalid qid format"
                    })
                    break

            # Check coordinates are valid
            for row in rows:
                try:
                    lat = float(row.get("latitude", ""))
                    lon = float(row.get("longitude", ""))

                    if not (-90 <= lat <= 90):
                        results.append({
                            "check_name": "t08_coordinates_valid",
                            "passed": False,
                            "message": "t08_pois_clean.csv has invalid latitude"
                        })
                        break

                    if not (-180 <= lon <= 180):
                        results.append({
                            "check_name": "t08_coordinates_valid",
                            "passed": False,
                            "message": "t08_pois_clean.csv has invalid longitude"
                        })
                        break
                except ValueError:
                    results.append({
                        "check_name": "t08_coordinates_valid",
                        "passed": False,
                        "message": "t08_pois_clean.csv has non-numeric coordinates"
                    })
                    break

            results.append({
                "check_name": "t08_has_pois",
                "passed": True,
                "message": f"t08_pois_clean.csv has {len(rows)} valid POI records"
            })
    except Exception as e:
        results.append({
            "check_name": "t08_validation",
            "passed": False,
            "message": f"Error validating t08_pois_clean.csv: {str(e)}"
        })

    return results

def validate_accessibility(filepath):
    """Validate t10_accessibility_scores.csv"""
    results = []

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": "t10_has_scores",
                    "passed": False,
                    "message": "t10_accessibility_scores.csv has no data rows"
                })
                return results

            # Check accessibility_score is between 0 and 1
            for row in rows:
                try:
                    score = float(row.get("accessibility_score", ""))

                    if not (0 <= score <= 1):
                        results.append({
                            "check_name": "t10_score_range",
                            "passed": False,
                            "message": "t10_accessibility_scores.csv has out-of-range accessibility_score"
                        })
                        break
                except ValueError:
                    results.append({
                        "check_name": "t10_score_range",
                        "passed": False,
                        "message": "t10_accessibility_scores.csv has non-numeric accessibility_score"
                    })
                    break

            # Check distance_m is non-negative
            for row in rows:
                try:
                    distance = float(row.get("distance_m", ""))

                    if distance < 0:
                        results.append({
                            "check_name": "t10_distance_valid",
                            "passed": False,
                            "message": "t10_accessibility_scores.csv has negative distance"
                        })
                        break
                except ValueError:
                    results.append({
                        "check_name": "t10_distance_valid",
                        "passed": False,
                        "message": "t10_accessibility_scores.csv has non-numeric distance"
                    })
                    break

            results.append({
                "check_name": "t10_has_scores",
                "passed": True,
                "message": f"t10_accessibility_scores.csv has {len(rows)} valid accessibility records"
            })
    except Exception as e:
        results.append({
            "check_name": "t10_validation",
            "passed": False,
            "message": f"Error validating t10_accessibility_scores.csv: {str(e)}"
        })

    return results

def validate_clusters(filepath):
    """Validate t13_city_clusters.csv"""
    results = []

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            if len(rows) == 0:
                results.append({
                    "check_name": "t13_has_clusters",
                    "passed": False,
                    "message": "t13_city_clusters.csv has no data rows"
                })
                return results

            # Check cluster_id is numeric
            for row in rows:
                try:
                    cluster_id = int(row.get("cluster_id", ""))
                except ValueError:
                    results.append({
                        "check_name": "t13_cluster_id_valid",
                        "passed": False,
                        "message": "t13_city_clusters.csv has non-numeric cluster_id"
                    })
                    break

            # Check member_count is positive
            for row in rows:
                try:
                    member_count = int(row.get("member_count", ""))

                    if member_count <= 0:
                        results.append({
                            "check_name": "t13_member_count_valid",
                            "passed": False,
                            "message": "t13_city_clusters.csv has non-positive member_count"
                        })
                        break
                except ValueError:
                    results.append({
                        "check_name": "t13_member_count_valid",
                        "passed": False,
                        "message": "t13_city_clusters.csv has non-numeric member_count"
                    })
                    break

            results.append({
                "check_name": "t13_has_clusters",
                "passed": True,
                "message": f"t13_city_clusters.csv has {len(rows)} valid cluster records"
            })
    except Exception as e:
        results.append({
            "check_name": "t13_validation",
            "passed": False,
            "message": f"Error validating t13_city_clusters.csv: {str(e)}"
        })

    return results

if __name__ == "__main__":
    results = validate_pipeline_outputs()
    print(f"Validation complete. Results written to {SUMMARY_FILE}")
    print(f"Total checks: {len(results)}")
    passed = sum(1 for r in results if r["passed"])
    print(f"Passed: {passed}/{len(results)}")
